from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def mk(amt="80.00", status="captured"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# partial then full
p=mk(); outage_refund(p,Decimal("30.00"),T0); assert p.refunded_amount==Decimal("30.00") and p.status=="captured"
outage_refund(p,Decimal("50.00"),T0); assert p.refunded_amount==Decimal("80.00") and p.status=="refunded"
print("partial/full ok")

# over refund
p=mk()
try: outage_refund(p,Decimal("80.01"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)

# non-captured
p=mk(status="authorized")
try: outage_refund(p,Decimal("1.00"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)

# non-positive
p=mk()
for a in [Decimal("0"),Decimal("-1")]:
    try: outage_refund(p,a,T0); print("FAIL")
    except BillingError as e: print("amount:",e.code)

# float rejected
p=mk()
try: outage_refund(p,1.0,T0); print("FAIL")
except BillingError as e: print("float:",e.code)

# approval threshold 1000
p=mk("2000.00")
try: outage_refund(p,Decimal("1000.01"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
outage_refund(p,Decimal("1000.00"),T0); print("at threshold ok")
outage_refund(p,Decimal("1000.01"),T0,approved_by="mgr"); print("approved ok")

# idempotency
p=mk(); audit.clear()
outage_refund(p,Decimal("10.00"),T0,idempotency_key="k1")
outage_refund(p,Decimal("10.00"),T0,idempotency_key="k1")
assert p.refunded_amount==Decimal("10.00"); print("idempotent ok")

# naive datetime
p=mk()
try: outage_refund(p,Decimal("1.00"),datetime(2026,10,1)); print("FAIL")
except BillingError as e: print("naive:",e.code)
